-- BLACK MOON Oct 31 release. Run after schema.sql, upgrade_entry_capacity.sql, 20261027_payment_methods.sql.
-- Existing bookings preserved. This migration enables solo ladies, venue details and inquiries.
BEGIN;
ALTER TABLE public.bookings DROP CONSTRAINT IF EXISTS bookings_guest_count_check;
ALTER TABLE public.bookings ADD CONSTRAINT bookings_guest_count_check CHECK (guest_count BETWEEN 1 AND 200);
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS booking_type text NOT NULL DEFAULT 'couple';
ALTER TABLE public.bookings DROP CONSTRAINT IF EXISTS bookings_booking_type_check;
ALTER TABLE public.bookings ADD CONSTRAINT bookings_booking_type_check CHECK (booking_type IN ('female','ladies','couple','group'));
ALTER TABLE public.event_config ADD COLUMN IF NOT EXISTS venue_address text NOT NULL DEFAULT '';
ALTER TABLE public.event_config ADD COLUMN IF NOT EXISTS public_area text NOT NULL DEFAULT 'Bahrain';
ALTER TABLE public.event_config ADD COLUMN IF NOT EXISTS entry_instructions text NOT NULL DEFAULT 'Present your QR ticket at entry. No entry without a confirmed reservation. Cash or verified bank transfer only.';
CREATE TABLE IF NOT EXISTS public.inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,contact text,message text NOT NULL,auto_reply text,admin_reply text,created_at timestamptz NOT NULL DEFAULT now(),replied_at timestamptz);
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inquiries FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.validate_guests(p_guests jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE n int;g jsonb;BEGIN IF jsonb_typeof(p_guests) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Guest list must be an array';END IF;n:=jsonb_array_length(p_guests);IF n<1 OR n>200 THEN RAISE EXCEPTION 'Guest count must be 1–200';END IF;FOR g IN SELECT value FROM jsonb_array_elements(p_guests) LOOP IF length(trim(coalesce(g->>'name','')))<2 OR length(trim(coalesce(g->>'name','')))>100 OR length(trim(coalesce(g->>'phone','')))<6 OR length(trim(coalesce(g->>'phone','')))>30 THEN RAISE EXCEPTION 'Each guest requires a valid name and phone';END IF;END LOOP;RETURN n;END$$;
-- Replace the 3-arg RPC with 4-arg RPC. Keep all capacity and guest checks server-side.
CREATE OR REPLACE FUNCTION public.create_public_booking(p_guests jsonb,p_email text,p_payment_method text,p_booking_type text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE n int;b public.bookings%rowtype;g jsonb;cfg public.event_config%rowtype;BEGIN n:=public.validate_guests(p_guests);IF length(coalesce(p_email,''))>254 THEN RAISE EXCEPTION 'Email too long';END IF;IF p_payment_method NOT IN ('cash','transfer') THEN RAISE EXCEPTION 'Invalid payment method';END IF;IF p_booking_type NOT IN ('female','ladies','couple','group') OR (p_booking_type='female' AND n<>1) OR (p_booking_type='ladies' AND n<2) OR (p_booking_type='couple' AND n<>2) OR (p_booking_type='group' AND (n<2 OR n%2<>0)) THEN RAISE EXCEPTION 'Invalid reservation type or guest count';END IF;SELECT * INTO cfg FROM public.event_config WHERE id=1;IF NOT cfg.booking_open THEN RAISE EXCEPTION 'Reservations are closed';END IF;INSERT INTO public.bookings(guest_count,email,amount_due,payment_method,booking_type) VALUES(n,nullif(trim(p_email),''),n*cfg.price_per_guest,p_payment_method,p_booking_type) RETURNING * INTO b;FOR g IN SELECT value FROM jsonb_array_elements(p_guests) LOOP INSERT INTO public.guests(booking_id,full_name,phone) VALUES(b.id,trim(g->>'name'),trim(g->>'phone'));END LOOP;INSERT INTO public.notifications(title,message,booking_id) VALUES('New reservation',b.reference||' requests '||n||' guests; '||p_booking_type||'; payment '||p_payment_method,b.id);RETURN jsonb_build_object('id',b.id,'reference',b.reference);END$$;
REVOKE ALL ON FUNCTION public.create_public_booking(jsonb,text,text,text) FROM public;
GRANT EXECUTE ON FUNCTION public.create_public_booking(jsonb,text,text,text) TO anon,authenticated;
DROP FUNCTION IF EXISTS public.create_public_booking(jsonb,text,text);
CREATE OR REPLACE FUNCTION public.get_ticket(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE b public.bookings%rowtype;c public.event_config%rowtype;BEGIN SELECT * INTO b FROM public.bookings WHERE id=p_id;IF NOT FOUND THEN RETURN null;END IF;SELECT * INTO c FROM public.event_config WHERE id=1;RETURN jsonb_build_object('reference',b.reference,'status',b.status,'guest_count',b.guest_count,'amount_due',b.amount_due,'payment_method',b.payment_method,'venue_address',CASE WHEN b.status='confirmed' THEN c.venue_address ELSE null END,'entry_instructions',CASE WHEN b.status='confirmed' THEN c.entry_instructions ELSE null END,'entry_token',CASE WHEN b.status='confirmed' THEN b.entry_token::text ELSE null END);END$$;
CREATE OR REPLACE FUNCTION public.public_event_details() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('public_area',public_area,'start_time','2026-10-31T02:00:00+03:00') FROM public.event_config WHERE id=1$$;
REVOKE ALL ON FUNCTION public.public_event_details() FROM public;GRANT EXECUTE ON FUNCTION public.public_event_details() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.admin_event_details() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE result jsonb;BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied';END IF;SELECT jsonb_build_object('venue_address',venue_address,'entry_instructions',entry_instructions,'public_area',public_area) INTO result FROM public.event_config WHERE id=1;RETURN result;END$$;
CREATE OR REPLACE FUNCTION public.admin_save_event_details(p_address text,p_instructions text,p_area text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied';END IF;IF length(coalesce(p_address,''))>1500 OR length(coalesce(p_instructions,''))>2000 OR length(coalesce(p_area,''))>150 THEN RAISE EXCEPTION 'Text too long';END IF;UPDATE public.event_config SET venue_address=coalesce(p_address,''),entry_instructions=coalesce(p_instructions,''),public_area=coalesce(p_area,'Bahrain') WHERE id=1;END$$;
CREATE OR REPLACE FUNCTION public.submit_inquiry(p_name text,p_contact text,p_message text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE result uuid;BEGIN IF length(trim(coalesce(p_name,''))) NOT BETWEEN 2 AND 100 OR length(coalesce(p_contact,''))>100 OR length(trim(coalesce(p_message,''))) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'Invalid inquiry';END IF;INSERT INTO public.inquiries(name,contact,message) VALUES(trim(p_name),left(trim(coalesce(p_contact,'')),100),trim(p_message)) RETURNING id INTO result;RETURN left(result::text,8);END$$;
CREATE OR REPLACE FUNCTION public.admin_inquiries() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE result jsonb;BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied';END IF;SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.created_at DESC),'[]'::jsonb) INTO result FROM (SELECT * FROM public.inquiries ORDER BY created_at DESC LIMIT 200)i;RETURN result;END$$;
CREATE OR REPLACE FUNCTION public.admin_reply_inquiry(p_id uuid,p_reply text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied';END IF;IF length(trim(coalesce(p_reply,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid reply';END IF;UPDATE public.inquiries SET admin_reply=trim(p_reply),replied_at=now() WHERE id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Inquiry not found';END IF;END$$;
REVOKE ALL ON FUNCTION public.admin_event_details(),public.admin_save_event_details(text,text,text),public.admin_inquiries(),public.admin_reply_inquiry(uuid,text),public.submit_inquiry(text,text,text) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.admin_event_details(),public.admin_save_event_details(text,text,text),public.admin_inquiries(),public.admin_reply_inquiry(uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.submit_inquiry(text,text,text) TO anon,authenticated;
COMMIT;
